#include <bits/stdc++.h>
using namespace std;

bool isAnagram(string s, string t) {
    if (s.size() != t.size()) return false;
    unordered_map<char, int> counts;
    for (char ch : s) counts[ch]++;                                // tally every letter in s
    for (char ch : t) {
        if (counts[ch] == 0) return false;
        counts[ch]--;                                                // subtract as each letter of t is consumed
    }
    return true;
}

int main() {
    string s = "anagram";
    string t = "nagaram";
    cout << (isAnagram(s, t) ? "true" : "false") << endl;
    return 0;
}
